phase1.code:
use std::io;

fn main() {
    println!("=== Rust CLI Calculator ===");

    // Get first number
    println!("Enter first number: ");
    let a = get_number();

    // Get operation
    println!("Enter operation (+, -, *, /): ");
    let op = get_operation();

    // Get second number
    println!("Enter second number: ");
    let b = get_number();

    // Calculate result
    let result = calculate(a, b, op);

    // Display result
    println!("{} {} {} = {}", a, op, b, result);
}

fn get_number() -> f64 {
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let num: f64 = input.trim().parse().expect("Please enter a valid number");
    num
}

fn get_operation() -> char {
    let mut input = String::new();
    io::stdin().read_line(&mut input).expect("Failed to read line");
    let op = input.trim().chars().next().expect("Please enter an operator");
    op
}

fn calculate(a: f64, b: f64, op: char) -> f64 {
    match op {
        '+' => a + b,
        '-' => a - b,
        '*' => a * b,
        '/' => a / b,
        _ => {
            println!("Invalid operation! Using addition.");
            a + b
        }
    }
}

